import {validateExtensions} from './save-extensions.js';
import {weaponClass} from './commerce.js';
import {ITEMS} from './inventory.js';
export const SAVE_KEY='hanskoy-game.save.v1', BACKUP_KEY=SAVE_KEY+'.backup';
const stages=new Set(['safe','offer','smith','armed','wolf','report','forest','carcasses','delivery','complete','mary_offer','water','ambush','water_return','mary_done','hunter_travel','hunter_search','hunter_talk','hunter_return','witch_offer','witch','witch_return','witch_done','bones_talk','bones_collect','bones_return','bones_done','page_search','page_return','trial_ready','trial_fight','trial_return','ritual_done']);
const finite=(n,min=-1e8,max=1e8)=>Number.isFinite(n)&&n>=min&&n<=max;
const vector=v=>Array.isArray(v)&&v.length===3&&v.every(n=>finite(n,-10000,10000));
function require(ok){if(!ok)throw new Error('Файл повреждён или не является сохранением этой версии игры.')}
function actor(a){require(a&&vector(a.position)&&typeof a.visible==='boolean'&&typeof a.hit==='boolean');for(const k of ['hp','maxHp','heading','generation','cooldown','timer','stun','slow','attackWindup'])require(a[k]===undefined||finite(a[k]));for(const k of ['home','target','patrolTarget','aggro','aggroOrigin'])require(a[k]===null||vector(a[k]));require(a.mode===undefined||['attack','return'].includes(a.mode))}
function projectile(b){require(b&&vector(b.position)&&vector(b.velocity)&&finite(b.age,0,10)&&finite(b.damage,0,1000000));}
export function validateSave(s){require(s?.game==='hanskoy-game'&&s.version===1&&typeof s.savedAt==='string'&&Number.isFinite(Date.parse(s.savedAt)));const p=s.chapter?.p;require(p&&stages.has(p.stage)&&[null,'sword','bow','mage'].includes(p.classId));require(Number.isInteger(p.level)&&p.level>=1&&p.level<=10000&&finite(p.xp,0,249)&&Number.isInteger(p.pendingLevels)&&p.pendingLevels>=0&&p.pendingLevels<p.level);require(p.gold===undefined||(Number.isSafeInteger(p.gold)&&p.gold>=0&&p.gold<=1000000000));require(typeof p.rejected==='boolean'&&typeof p.wolfDead==='boolean'&&finite(p.arrows,0,1000000));require(Array.isArray(p.rewards)&&p.rewards.length<=20000&&p.rewards.every(id=>typeof id==='string'&&id.length<150));if(s.chapter.chest!==undefined){require(Array.isArray(s.chapter.chest)&&s.chapter.chest.length===18);s.chapter.chest.forEach(i=>require(i===null||(i&&Object.hasOwn(ITEMS,i.id)&&Number.isInteger(i.count)&&i.count>0&&i.count<=1000000)))}if(s.chapter.combat!==undefined){const c=s.chapter.combat;require(c&&Number.isInteger(c.rank)&&c.rank>=0&&c.rank<=Math.floor((p.level-1)/2)&&finite(c.skillReady,0)&&finite(c.rollReady,0));}if(s.chapter.combat?.mageShots!==undefined)require(Number.isInteger(s.chapter.combat.mageShots)&&s.chapter.combat.mageShots>=0&&s.chapter.combat.mageShots<3);const slots=s.chapter.slots;require(Array.isArray(slots)&&[18,20].includes(slots.length));slots.forEach((item,i)=>{if(item===null)return;require(item&&Object.hasOwn(ITEMS,item.id)&&Number.isInteger(item.count)&&item.count>0&&item.count<=1000000);require((i>=6&&i<18)||(i>=18?ITEMS[item.id].slot==='ring':ITEMS[item.id].slot===i))});require(!slots[0]||slots[0].id==='torch'||weaponClass(slots[0].id)===p.classId);require(Array.isArray(s.chapter.bullets)&&s.chapter.bullets.length<=100);s.chapter.bullets.forEach(b=>{projectile(b);require(b.straight===undefined||typeof b.straight==='boolean');require(b.slow===undefined||finite(b.slow,0,7));require(typeof b.arrow==='boolean'&&finite(b.delay,0,1))});for(const k of ['lastAttack','lastHurt','attackTime'])require(finite(s.chapter[k]));const v=s.player?.vitals;require(v&&vector(s.player.position)&&finite(s.player.yaw)&&finite(s.player.pitch,-1.35,1.35));for(const [key,max] of [['hp','maxHp'],['mana','maxMana'],['stamina','maxStamina']]){require(finite(v[max],100,100100)&&finite(v[key],0,v[max]))}require(finite(v.height,0,10)&&finite(v.velocity,-100,100));require(finite(s.elapsed,0)&&Number.isInteger(s.seed)&&s.seed>=0&&s.seed<=4294967295&&typeof s.muted==='boolean');require(Array.isArray(s.actors)&&s.actors.length===8);s.actors.forEach(actor);
const w=s.world;if(w?.troll!==undefined){const t=w.troll;actor(t.actor);require(t.actor.id==='troll'&&t.actor.maxHp===400&&finite(t.actor.hp,0,400)&&Number.isInteger(t.serial)&&t.serial>=0&&finite(t.windup,0,.9)&&typeof t.slam==='boolean'&&finite(t.slamReady,0,8)&&finite(t.clock,0));}require(w&&typeof w.inside==='boolean'&&typeof w.witchActive==='boolean'&&finite(w.time,0)&&Array.isArray(w.mobs)&&w.mobs.length===(w.witchActive?36:35));const expected=new Set(Array.from({length:35},(_,i)=>i<30?'deep-'+(i%3===0?'hare':'wolf')+'-'+i:'deep-raven-'+i));if(w.witchActive)expected.add('witch');w.mobs.forEach(a=>{actor(a);require(expected.delete(a.id))});require(expected.size===0);actor(w.witch);if(w.hunter!==undefined){actor(w.hunter);require(w.hunter.id==='hunter'&&finite(w.hunter.hp,0,75)&&w.hunter.maxHp===75)}require(Array.isArray(w.drops)&&w.drops.length<=2000);w.drops.forEach(d=>require(['carcass','fang','gold','shield_fine','quiver','grimoire','witch_relic'].includes(d.id)&&vector(d.position)&&finite(d.phase)&&(d.count===undefined||(Number.isInteger(d.count)&&d.count>=1&&d.count<=(d.id==='gold'?50:1)))));require(Array.isArray(w.shots)&&w.shots.length<=100);w.shots.forEach(b=>{projectile(b);require(typeof b.large==='boolean'&&(b.arrow===undefined||typeof b.arrow==='boolean')&&(b.delay===undefined||finite(b.delay,0,1)))});
if(w.boss!==undefined){const b=w.boss;for(const key of ['poolReady','laughReady'])require(b[key]===undefined||finite(b[key],0));require(b.witchEngaged===undefined||typeof b.witchEngaged==='boolean');require(b&&finite(b.time,0)&&typeof b.healUsed==='boolean'&&finite(b.healLeft,0,10)&&Array.isArray(b.shots)&&b.shots.length<=100&&Array.isArray(b.pools)&&b.pools.length<=30);b.shots.forEach(s=>{projectile(s);for(const k of ['arrow','large','falling'])require(typeof s[k]==='boolean');require(finite(s.delay,0,1))});b.pools.forEach(p=>require(vector(p.position)&&finite(p.age,0,10)&&finite(p.exposure,0,10)))}const e=s.encounter;require(e&&typeof e.started==='boolean'&&Array.isArray(e.mobs)&&e.mobs.length===(e.started?3:0));e.mobs.forEach((a,i)=>{actor(a);require(a.id==='lake-wolf-'+i)});require(!['ambush','water_return','mary_done'].includes(p.stage)||e.started);if(s.cemetery!==undefined){const c=s.cemetery;require(c?.torchTaken===undefined||typeof c.torchTaken==='boolean');require(c&&typeof c.inside==='boolean'&&typeof c.built==='boolean'&&(!c.inside||c.built)&&finite(c.time,0)&&Array.isArray(c.mobs)&&c.mobs.length===(c.built?32:0)&&Array.isArray(c.drops)&&c.drops.length<=2000&&Array.isArray(c.shots)&&c.shots.length<=100);const ids=new Set(Array.from({length:c.built?32:0},(_,i)=>'cemetery-'+i));c.mobs.forEach(n=>{actor(n);require(ids.delete(n.id)&&n.maxHp===70&&finite(n.hp,0,70))});c.drops.forEach(d=>require(vector(d.position)&&finite(d.phase)));c.shots.forEach(b=>require(vector(b.position)&&vector(b.velocity)&&finite(b.age,0,5)&&typeof b.arrow==='boolean'));require(!c.inside||!w.inside)}if(s.dungeon?.mode){require(['dungeon','lich'].includes(s.dungeon.mode));require(s.player.position[0]>430&&s.player.position[0]<730)}else if(s.ritual?.mode){require(['hut','trial'].includes(s.ritual.mode)&&s.ritual.origin&&vector(s.ritual.origin.position)&&finite(s.ritual.origin.yaw)&&finite(s.ritual.origin.pitch));require(s.player.position[0]>101&&s.player.position[0]<139);if(s.ritual.mode==='trial')require(p.stage==='trial_fight'&&s.ritual.mirror&&s.ritual.params)}else{require((s.player.position[0]<-250)===!!s.cemetery?.inside);const inDeep=s.player.position[0]>180;require(inDeep===w.inside);}validateExtensions(s,require,finite,vector,actor,projectile);return s}
export function encodeSave(state){return JSON.stringify(validateSave({...state,game:'hanskoy-game',version:1,savedAt:new Date().toISOString()}))}
export function decodeSave(text){if(typeof text!=='string'||text.length>2000000)throw new Error('Файл сохранения слишком большой.');return validateSave(JSON.parse(text))}
export function saveStore(storage){return {read(){let corrupt=false;for(const key of [SAVE_KEY,BACKUP_KEY]){const raw=storage.getItem(key);if(!raw)continue;try{return {data:decodeSave(raw),backup:key===BACKUP_KEY}}catch{corrupt=true}}return {data:null,corrupt}},write(state){const raw=encodeSave(state),old=storage.getItem(SAVE_KEY);if(old){try{decodeSave(old);storage.setItem(BACKUP_KEY,old)}catch(error){if(error?.name==='QuotaExceededError')throw error}}storage.setItem(SAVE_KEY,raw);return raw},clear(){storage.removeItem(SAVE_KEY);storage.removeItem(BACKUP_KEY)}}}
